import React, { useState } from 'react';
import { Smile, RefreshCw, ChevronLeft, ChevronRight, Loader2 } from 'lucide-react';
import { JarvisMark } from './LiveTerminal';

// JARVIS Humor: lines generated by Gemini in JARVIS's own voice (/api/humor), with the offline
// stash when Gemini is busy (labelled as such). Keeps a short history to page back through.

const KINDS = ['JOKE', 'ROAST', 'SARCASM', 'DAD JOKE', 'RANDOM', 'FUN FACT'] as const;
interface Line { kind: string; text: string; source: 'ai' | 'offline' }
const EMOJI: Record<string, string> = { JOKE: '😄', ROAST: '🔥', SARCASM: '🙃', 'DAD JOKE': '🤦', RANDOM: '🎲', 'FUN FACT': '💡' };

export const JarvisHumor: React.FC = () => {
  const [kind, setKind] = useState<(typeof KINDS)[number]>('JOKE');
  const [lines, setLines] = useState<Line[]>([]);
  const [at, setAt] = useState(-1);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchLine = async (k: (typeof KINDS)[number] = kind) => {
    if (loading) return;
    setKind(k);
    setLoading(true);
    setError(null);
    try {
      const r = await fetch('/api/humor', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ kind: k, recent: lines.map((l) => l.text) }),
      });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      const d = (await r.json()) as Line;
      setLines((ls) => { const next = [...ls, d].slice(-10); setAt(next.length - 1); return next; });
    } catch {
      setError("Humor core offline. Couldn't reach J.A.R.V.I.S.");
    } finally {
      setLoading(false);
    }
  };

  const line = lines[at];
  return (
    <div className="jv-hud">
      <div className="jv-hud-head">
        <div className="jv-hud-title"><Smile className="w-4 h-4" /><span><span className="jv-t-full">JARVIS Humor</span><span className="jv-t-short">Humor</span></span></div>
        <button className="jv-icon-btn w-5 h-5 !text-[var(--dc)]/70 hover:!text-[var(--dc)]" onClick={() => fetchLine()} disabled={loading} title={`Another ${kind.toLowerCase()}`} aria-label="Another one">
          <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
        </button>
      </div>
      <div className="jv-hud-body flex flex-col gap-2.5">
        {/* JARVIS's line */}
        <div className="flex gap-2.5 flex-1 min-h-[64px] min-w-0">
          <div className="jv-avatar jarvis !w-7 !h-7 !mt-0.5"><JarvisMark /></div>
          <div className="flex flex-col min-w-0 flex-1 min-h-0">
            <div className="flex items-center justify-between gap-1 mb-1">
              <span className="jv-glow-c font-bold tracking-widest text-[11.5px] truncate">JARVIS{line ? ` // ${line.kind}` : ''}</span>
              {line?.source === 'offline' && <span className="text-[9px] font-bold tracking-widest jv-glow-y shrink-0" title="Gemini was busy: from JARVIS's built-in stash">STASH</span>}
            </div>
            <div className="text-gray-200 text-[12.5px] leading-relaxed flex-1 min-h-0 overflow-y-auto">
              {loading && !line ? <span className="flex items-center gap-1.5 text-[var(--dgray-l)]"><Loader2 className="w-3.5 h-3.5 animate-spin" />Warming up the wit…</span>
                : line ? <>&ldquo;{line.text}&rdquo;<span className="block mt-1 text-[15px]" aria-hidden="true">{EMOJI[line.kind] ?? '😄'}</span></>
                : <span className="text-[var(--dgray-l)]">Pick a mood below and I'll brighten your day.</span>}
            </div>
          </div>
        </div>

        {/* Pager: previous lines this session */}
        <div className={`jv-pager flex items-center justify-between px-3 shrink-0 text-[var(--dgray)] ${lines.length > 1 ? '' : 'empty'}`}>
          <button className="jv-icon-btn w-5 h-5" onClick={() => setAt((i) => Math.max(0, i - 1))} disabled={at <= 0} aria-label="Previous line"><ChevronLeft className="w-4 h-4" /></button>
          <div className="flex gap-1.5 min-w-0 overflow-hidden">
            {(lines.length ? lines : [null, null, null]).map((_, i) => (
              <span key={i} className={`w-1.5 h-1.5 rounded-full shrink-0 ${lines.length && i === at ? 'bg-[var(--dc)] shadow-[0_0_6px_var(--dc)]' : 'bg-[var(--dc)]/30'}`} />
            ))}
          </div>
          <button className="jv-icon-btn w-5 h-5" onClick={() => setAt((i) => Math.min(lines.length - 1, i + 1))} disabled={at >= lines.length - 1} aria-label="Next line"><ChevronRight className="w-4 h-4" /></button>
        </div>

        <div className="jv-humor-grid">
          {KINDS.map((k) => (
            <button key={k} className={`jv-btn ${k === kind ? 'on' : ''}`} onClick={() => fetchLine(k)} disabled={loading} aria-pressed={k === kind}>{k}</button>
          ))}
        </div>
        {error && <div className="text-[10px] text-rose-300 shrink-0 jv-mono">{error}</div>}
      </div>
    </div>
  );
};
